use concir_sync::Semaphore;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn main() {
    let c = Arc::new(AtomicUsize::new(0));
    let semaphore = Semaphore::new(2);

    let c1 = Arc::clone(&c);
    let semaphore1 = Arc::clone(&semaphore);
    let w1 = thread::spawn(move || {
        let permit = semaphore1.acquire();
        let mut current = c1.load(Ordering::SeqCst);
        loop {
            match c1.compare_exchange(
                current,
                current + 1,
                Ordering::SeqCst,
                Ordering::SeqCst,
            ) {
                Ok(_) => break,
                Err(actual) => current = actual,
            }
        }
        permit.release();
    });

    let c2 = Arc::clone(&c);
    let semaphore2 = Arc::clone(&semaphore);
    let w2 = thread::spawn(move || {
        let permit = semaphore2.acquire();
        let mut current = c2.load(Ordering::SeqCst);
        loop {
            match c2.compare_exchange(
                current,
                current + 1,
                Ordering::SeqCst,
                Ordering::SeqCst,
            ) {
                Ok(_) => break,
                Err(actual) => current = actual,
            }
        }
        permit.release();
    });

    w1.join().unwrap();
    w2.join().unwrap();

    assert_eq!(c.load(Ordering::SeqCst), 2);
    println!("DONE done=1");
}
